@if (selectedId() === undefined) {
  <nav aria-labelledby="parks-heading">
    <h2 id="parks-heading" tabindex="-1" #listHeading>Parks</h2>
    @if (loading()) {
      <p role="status">Loading parks…</p>
    } @else if (error()) {
      <p role="alert">{{ error() }}</p>
    } @else if (parks().length === 0) {
      <p>No parks to show.</p>
    } @else {
      <ul class="park-list">
        @for (park of parks(); track park.id) {
          <li>
            <a #parkLink [routerLink]="['/parks', park.id]" [attr.data-park-id]="park.id"
              ><svg
                class="pin"
                aria-hidden="true"
                viewBox="0 0 28 40"
                width="14"
                height="20"
                [style.color]="pinColor($index)"
              >
                <path fill="currentColor" [attr.d]="PIN_PATH" /></svg
              >{{ park.name }}</a
            >
          </li>
        }
      </ul>
    }
  </nav>
} @else if (loading()) {
  <p role="status">Loading parks…</p>
} @else if (error()) {
  <p role="alert">{{ error() }}</p>
} @else {
  @if (selected(); as park) {
    <article>
      <h2 tabindex="-1" #detailsHeading>{{ park.name }}</h2>
      <div class="summary">
        <dl>
          <dt>Location</dt>
          <dd>
            @if (park.address !== null) {
              {{ park.address }}
            } @else if (park.coordinates !== null) {
              {{ park.coordinates.lat }}, {{ park.coordinates.lng }}
            } @else {
              Location not available
            }
          </dd>
          @if (park.hours !== null) {
            <dt>Hours</dt>
            <dd>{{ park.hours }}</dd>
          }
          @if (park.acreage !== null) {
            <dt>Size</dt>
            <dd>{{ park.acreage }} acres</dd>
          }
          @if (park.rating !== null) {
            <dt>Rating</dt>
            <dd>{{ park.rating }}</dd>
          }
        </dl>
        <div class="preview">
          @if (park.images.length > 0) {
            <app-park-image class="thumb" aria-hidden="true" [src]="park.images[0]" alt="" />
          }
          @if (park.amenities.length > 0) {
            <p class="emoji-row" aria-hidden="true">
              @for (amenity of park.amenities; track $index) {
                {{ amenityEmoji(amenity) }}
              }
            </p>
          }
        </div>
      </div>
      <h3>Description</h3>
      <p>{{ park.description ?? 'No description available.' }}</p>
      @if (park.amenities.length > 0) {
        <h3>Amenities</h3>
        <ul class="amenities">
          @for (amenity of park.amenities; track $index) {
            <li>
              <span class="emoji" aria-hidden="true">{{ amenityEmoji(amenity) }}</span>
              <span class="label">{{ amenity }}</span>
            </li>
          }
        </ul>
      }
      <h3>{{ park.images.length > 1 ? 'Photos' : 'Photo' }}</h3>
      @if (park.images.length === 0) {
        <app-park-image [src]="null" [alt]="park.name + ' photo'" />
      } @else {
        <div class="gallery">
          @for (image of park.images; track $index) {
            <app-park-image
              [src]="image"
              [alt]="
                park.images.length > 1 ? park.name + ' photo ' + ($index + 1) : park.name + ' photo'
              "
            />
          }
        </div>
      }
    </article>
  } @else {
    <h2 tabindex="-1" #detailsHeading>Park not found</h2>
  }
}
